import {signInView,accountSecurityView,pendingSaveView} from './account-view.mjs?v=3.8';
import {VERSION,answerCount} from './instrument.mjs';
import {AI_SCOPES,buildAIInput,selectForAI,factValues,factNote} from './ai-input.mjs';
import {currentPublicProfile} from './self-comparison.mjs';
import {INTIMACY_VERSION,intimateCount,PRACTICE_CHOICES} from './extensions-data.mjs';
import {compareProfiles,comparisonLabels,mapTemperament,comparisonSources} from './comparison.mjs?v=3.5';
import {methodNav} from './extensions.mjs?v=3.9';
import {drawCard,saveCanvas} from './share-cards.mjs';
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=v=>v===null?'—':v.toLocaleString('cs-CZ',{maximumFractionDigits:2});
const date=t=>new Date(t*1000).toLocaleString('cs-CZ',{dateStyle:'medium',timeStyle:'short'});
const names={personality:'Osobnost a temperament',roles:'Intimní role',context:'Kontext intimity',practices:'Preference aktivit'};
const head=(eyebrow,title,lead)=>`<div class="wrap page-head"><span class="eyebrow">${eyebrow}</span><h1>${title}</h1><p class="lead">${lead}</p></div>`;
const limits=`<aside class="notice"><span class="notice-symbol">i</span><div><strong>Popis odpovědí, nikoli předpověď vztahu</strong><p>Vlastní české dotazníky nejsou validované. Podobnost nezaručuje spokojenost; rozdíl není chyba. <a href="#podklady-porovnani">Výzkum, pravidla a co z toho nelze vyčíst →</a></p></div></aside>`;
export const accountCallout=`<div class="wrap share-callout"><div><span class="eyebrow">ULOŽIT A POROVNAT</span><h2>Dva lidé. Dva pohledy.</h2><p>Ulož výsledek, vyber části ke sdílení a získej kód pro porovnání.</p></div><div class="actions"><a class="button" href="#ucet">Účet a uložené výsledky ↗</a><a class="text-link" href="#porovnani">Porovnat dva kódy →</a></div></div>`;
export function createProfiles({show,go,getPersonality,getIntimacy,restore,clear}){
  const state={authMode:'login',authNickname:'',authRemember:false,nickname:null,legacy:false,remembered:false,pendingSave:null,ready:false,csrf:'',account:null,lastAccount:null,profiles:[],shares:[],selection:null,shareCode:null,grantScopes:['personality'],comparison:null,compareMode:'auto',comparisonView:'overview',selfScopes:['personality'],comparisonIsSelf:false,partnerCode:'',firstCode:'',ai:null,aiFocus:false,aiScopes:['personality'],busy:false,notice:'',error:'',pending:null};
  const cards=new Map();
  function chooseTab(button){
    if(button.dataset.compareView){const view=button.dataset.compareView;state.comparisonView=view;document.querySelectorAll('[id^="compare-view-"]').forEach(el=>el.hidden=el.id!=='compare-view-'+view);document.querySelectorAll('.comparison-views [role="tab"]').forEach(el=>{const yes=el.dataset.compareView===view;el.setAttribute('aria-selected',String(yes));el.tabIndex=yes?0:-1;});document.getElementById('view-tab-'+view)?.focus({preventScroll:true});document.querySelector('.comparison-views')?.scrollIntoView({block:'start',behavior:'instant'});}
    if(button.dataset.analysisTab){const scope=button.dataset.analysisTab;document.querySelectorAll('.ai-analysis').forEach(el=>el.hidden=el.dataset.analysisScope!==scope);document.querySelectorAll('[data-analysis-tab]').forEach(el=>{const yes=el.dataset.analysisTab===scope;el.setAttribute('aria-selected',String(yes));el.tabIndex=yes?0:-1;});button.closest('.analysis-tabs')?.scrollIntoView({block:'start',behavior:'instant'});}
  }
  document.addEventListener('click',event=>{const b=event.target.closest('[data-compare-view],[data-analysis-tab]');if(b)chooseTab(b);});
  document.addEventListener('keydown',event=>{const b=event.target.closest('[role="tab"]');if(!b||!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;const tabs=[...b.closest('[role="tablist"]').querySelectorAll('[role="tab"]')],i=tabs.indexOf(b),next=event.key==='Home'?0:event.key==='End'?tabs.length-1:(i+(event.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;event.preventDefault();chooseTab(tabs[next]);tabs[next].focus();});

  document.addEventListener('click',event=>{const button=event.target.closest('[data-expand-analysis]');if(!button)return;const article=button.closest('.ai-analysis'),items=[...article.querySelectorAll('.analysis-topic')],expand=items.some(item=>!item.open);items.forEach(item=>item.open=expand);button.textContent=expand?'Sbalit podrobné významy':'Rozbalit všechny významy v této kapitole';});

  const secure=()=>location.protocol==='https:'||['localhost','127.0.0.1'].includes(location.hostname);
  async function api(action,data={},retry=true){
    const expectedAccount=state.account;
    if(!state.ready){const res=await fetch('./api.php',{credentials:'same-origin',cache:'no-store'});const info=await res.json();if(!res.ok)throw Error(info.error||'Ukládání není dostupné.');acceptAuth(info);if(info.account)state.lastAccount=info.account;state.ready=true;if(action&&expectedAccount&&info.account!==expectedAccount)throw Error('Přihlášený účet se mezitím změnil. Zkontroluj ho a akci zopakuj.');}
    if(!action)return;
    const res=await fetch('./api.php',{method:'POST',credentials:'same-origin',cache:'no-store',headers:{'Content-Type':'application/json','X-CSRF-Token':state.csrf},body:JSON.stringify({action,...data})});
    const info=await res.json();if(!res.ok){if(res.status===403&&retry){state.ready=false;return api(action,data,false);}if(res.status===401){state.ready=false;if(!['login','legacy-login'].includes(action))state.account=null;}throw Error(info.error||'Akce se nepodařila.');}if(info.csrf)state.csrf=info.csrf;if(Object.hasOwn(info,'account'))acceptAuth(info);return info;
  }
  function acceptAuth(info){state.csrf=info.csrf;state.account=info.account;state.nickname=info.nickname;state.legacy=info.legacy;state.remembered=info.remembered;}
  async function savePending(){if(!state.pendingSave||!state.account)return;const pending=state.pendingSave;const r=await api('save',{snapshot:pending.snapshot});state.pendingSave=null;state.selection=r.id;state.grantScopes=pending.scope==='personality'?['personality']:[];state.preview=null;state.shareCode=null;state.notice='Výsledek je uložený. Najdeš ho kdykoliv ve svém účtu. Níže můžeš vybrat části pro párové porovnání.';await refreshList();}
  async function refreshList(){if(state.account){const data=await api('list');state.profiles=data.profiles;state.shares=data.shares;}else{state.profiles=[];state.shares=[];}}
  function feedback(){return `<div id="profile-feedback" class="wrap" role="status" aria-live="polite">${state.error?`<p class="feedback error">${esc(state.error)}</p>`:state.notice?`<p class="feedback">${esc(state.notice)}</p>`:''}</div>`;}
  function refresh(){route(location.hash,false);}
  async function run(fn){if(state.busy)return;state.busy=true;state.error='';state.notice='';document.querySelectorAll('[data-p],form[data-form] button').forEach(b=>b.disabled=true);try{await fn();}catch(e){state.error=e.message||'Nepodařilo se spojit se serverem. Odpovědi zůstaly na stránce.';}finally{state.busy=false;if(['#ucet','#porovnani'].includes(location.hash)){refresh();if(state.aiFocus&&location.hash==='#porovnani'){const output=document.getElementById('ai-result');output?.focus({preventScroll:true});output?.scrollIntoView({block:'start'});state.aiFocus=false;}if(location.hash==='#ucet'&&(state.preview||state.shareCode))document.getElementById('grant-preview')?.scrollIntoView({block:'center'});}}}
  const checks=(prefix,options=names)=>Object.entries(options).map(([id,label])=>`<label class="check-row"><input type="checkbox" id="${prefix}-${id}" ${(prefix==='grant'?state.grantScopes.includes(id):prefix==='self'?state.selfScopes.includes(id):id==='personality')?'checked':''}> ${label}</label>`).join('');
  function accountPage(){
    if(!secure())return head('PŘEJÍT NA HTTPS','Uložit bezpečným<br><em>připojením.</em>','Účty jsou dostupné na šifrované adrese. Pokud už máš odpovědi v této stránce, nejprve si je stáhni; otevření jiné adresy je nepřenese.')+`<div class="wrap"><a class="button" href="${esc(new URL(location.pathname+'#ucet','https://'+location.host).href)}">Otevřít HTTPS →</a></div>`;
    const start=head('ÚČET / DOBROVOLNÉ UKLÁDÁNÍ','Vrať se ke svému<br><em>vlastnímu profilu.</em>','Nickname a heslo, bez e-mailu. Uložené výsledky máš kdykoliv dostupné z účtu, i na jiném zařízení. Pro párové porovnávání si můžeš vytvořit odvolatelný kód.');
    if(!state.ready&&!state.error)return start+`<div class="wrap"><p role="status">Připojuji úložiště…</p></div>`;
    if(!state.account)return start+feedback()+pendingSaveView(state.pendingSave)+signInView(state);
    const countP=answerCount(getPersonality()),countI=intimateCount(getIntimacy());
    return start+feedback()+pendingSaveView(state.pendingSave)+(state.pendingSave?'<div class="wrap"><button class="button" data-p="retry-save">Uložit připravený výsledek</button></div>':'')+`<div class="wrap account-bar"><span>Přihlášený účet <strong>${esc(state.nickname||state.account)}</strong><br><small>${state.remembered?'Přihlášení zapamatováno na tomto zařízení':'Přihlášení pro tuto relaci'}</small></span><button class="text-button" data-p="logout">Odhlásit a vyčistit stránku</button></div>`+
    accountSecurityView(state)+
    `<div class="wrap profile-grid account-sections"><section class="paper"><span class="eyebrow">PRÁVĚ V TÉTO STRÁNCE</span><h2>Uložit nový výsledek.</h2><p>Osobnost ${countP}/50 · intimita ${countI}/38. Uloží se aktuální odpovědi vybraných modulů jako samostatný snímek. Starší výsledky se nepřepíšou.</p><form data-form="save">${checks('save',{personality:'Uložit osobnost a temperament',intimacy:'Uložit intimní odpovědi (citlivá data)'})}<label class="check-row consent-check"><input type="checkbox" required name="consent"> Chci vybrané odpovědi uložit na server. Rozumím <a href="#soukromi">podmínkám uložení</a>.</label><button class="button" type="submit" ${!countP&&!countI?'disabled':''}>Uložit vybrané odpovědi →</button></form><p class="fine-print">Intimní část je vždy dobrovolná. Účet ani uložený výsledek nejsou veřejné.</p></section><section class="paper"><span class="eyebrow">JAK POROVNÁNÍ FUNGUJE</span><h2>Vyber, co zpřístupníš.</h2><ol class="instruction-list"><li>Ulož výsledek a otevři „Vytvořit porovnávací kód“.</li><li>Vyber kategorie a zkontroluj jejich náhled. Intimní části jsou vypnuté.</li><li>Pošli partnerovi porovnávací kód. Oba kódy vložte do porovnání.</li></ol><a class="button secondary" href="#porovnani">Otevřít porovnání →</a></section></div>`+
    `<section class="wrap section"><div class="section-heading"><div><span class="eyebrow">ULOŽENÉ SNÍMKY</span><h2>Tvoje výsledky.</h2></div><span>${state.profiles.length}/20 uložených</span></div><div class="saved-list">${state.profiles.length?state.profiles.map(p=>`<article class="saved-item"><div><strong>${p.personalityCount&&p.intimacyCount?'Osobnost + intimní profil':p.intimacyCount?'Intimní profil':'Osobnost a temperament'}</strong><span>${date(p.created)} · ${p.personalityCount||0}/50 osobnost · ${p.intimacyCount||0}/38 intimita</span><code>${esc(p.id)}</code><span>ID výsledku samo o sobě data neotevře.</span></div><div class="actions"><button class="button secondary" data-p="select-share" data-id="${esc(p.id)}">Vytvořit porovnávací kód</button><button class="text-button" data-p="load" data-id="${esc(p.id)}">Načíst do stránky</button><button class="text-button" data-p="delete-profile" data-id="${esc(p.id)}">Smazat uložený výsledek</button></div></article>`).join(''):'<p>Zatím tu nemáš uložený výsledek.</p>'}</div></section>`+
    (state.selection?shareForm():'')+
    `<section class="wrap section"><h2>Vydané porovnávací kódy.</h2><p class="small">Kód funguje 7 dní. Umožňuje zobrazit vybrané části každému, kdo ho zná. Zrušením zabráníš dalšímu načtení; už zobrazené nebo stažené kopie tím nezmizí.</p>${state.shares.length?state.shares.map(s=>`<article class="saved-item"><div><code>${esc(s.profile_id)}</code><strong>${s.scopes.map(x=>names[x]).join(' · ')}</strong><span>${s.expires>Date.now()/1000?'Platí do':'Vypršel'} ${date(s.expires)}</span></div><button class="button secondary" data-p="revoke" data-id="${esc(s.id)}">Zrušit kód</button></article>`).join(''):'<p class="small">Žádné vydané kódy.</p>'}</section>`+
    `<section class="wrap danger-zone"><h2>Smazání účtu.</h2><p>Odstraní všechny uložené výsledky, zneplatní kódy i přihlášení a vyčistí tento panel i místní kopii v prohlížeči. Stažené soubory a kopie u dalších lidí zůstanou.</p><button class="button secondary" data-p="delete-account">Smazat účet a všechna jeho data</button></section>`+confirmDialog();
  }
  function shareForm(){return `<section class="wrap secret-box" id="share-builder"><span class="eyebrow">VYBRANÝ VÝSLEDEK ${esc(state.selection)}</span><h2>Co může druhý člověk vidět?</h2><form data-form="share">${checks('grant')}<p class="fine-print">Osobnost a role sdílejí průměry; kontext a aktivity jednotlivé vyplněné volby. „Nechci uvést“ se nesdílí. Kód neumožní upravovat ani mazat účet.</p><button class="button" type="submit">Zobrazit náhled vybraných částí →</button></form><div id="grant-preview">${grantDetails()}</div></section>`;}
  function confirmDialog(){return `<dialog id="account-confirm"><form method="dialog"><span class="eyebrow">POTVRDIT AKCI</span><h2 id="account-confirm-title">Pokračovat?</h2><p id="account-confirm-copy"></p><div id="account-confirm-input"></div><div class="actions"><button class="button secondary" value="cancel" formnovalidate>Zrušit</button><button class="button" value="confirm">Potvrdit</button></div></form></dialog>`;}
  function confirmAction(title,copy,fn,typed=false){const d=document.getElementById('account-confirm');state.pending=fn;document.getElementById('account-confirm-title').textContent=title;document.getElementById('account-confirm-copy').textContent=copy;document.getElementById('account-confirm-input').innerHTML=typed?'<label for="delete-word">Napiš SMAZAT</label><input id="delete-word" required pattern="SMAZAT" autocomplete="off"><label for="delete-secret">Aktuální heslo (u původního účtu klíč)</label><input id="delete-secret" type="password" required autocomplete="current-password">':'';d.returnValue='';d.addEventListener('close',()=>{const fn=state.pending;state.pending=null;if(d.returnValue==='confirm')run(fn);},{once:true});d.showModal();}
  function previewHTML(p){const rows=[];if(p.personality)rows.push(['Osobnost',Object.entries(p.personality).map(([k,v])=>`${k}: ${fmt(v)}`).join(' · ')]);if(p.roles)rows.push(['Role',Object.entries(p.roles).map(([k,v])=>`${k}: ${fmt(v)}`).join(' · ')]);if(p.context)rows.push(['Kontext',Object.entries(p.context).map(([k,v])=>`${k}: ${v==='na'?'Nevím / netýká se mě':v+' / 5'}`).join(' · ')||'Žádné sdělitelné odpovědi']);if(p.practices)rows.push(['Aktivity',Object.entries(p.practices).map(([k,v])=>`${k}: ${PRACTICE_CHOICES[v]||v}`).join(' · ')||'Žádné sdělitelné odpovědi']);return rows.map(([label,detail])=>`<p><strong>${label}</strong><br>${esc(detail)}</p>`).join('');}
  function comparePage(){
    const mine=answerCount(getPersonality()),intimate=intimateCount(getIntimacy()),self=state.compareMode==='self'||(state.compareMode==='auto'&&mine+intimate>0),loaded=Boolean(state.comparison);
    const entry='<details class="wrap compare-entry journey-entry" '+(!loaded?'open':'')+'><summary><strong>'+(loaded?'Profily jsou načtené':'1. Vyber profily')+'</strong><span>'+(loaded?'Změnit kódy nebo způsob porovnání':'Jeden partnerův kód, nebo dva uložené profily')+'</span></summary><div class="compare-modes" role="group" aria-label="Způsob porovnání"><button class="button '+(self?'':'secondary')+'" data-p="compare-mode" data-mode="self" aria-pressed="'+self+'">Moje odpovědi + kód</button><button class="button '+(!self?'':'secondary')+'" data-p="compare-mode" data-mode="codes" aria-pressed="'+(!self)+'">Dva kódy</button></div>'+
    (self?'<div class="self-note"><strong>Profil A = moje odpovědi v tomto prohlížeči</strong><p>Osobnost '+mine+'/50 · intimita '+intimate+'/38. '+(!mine&&!intimate?'<a href="#testy">Nejdřív vyplň některý test →</a>':'<a href="#profil">Otevřít můj profil →</a>')+'</p></div><form data-form="compare-self" class="self-compare-form"><div><label for="compare-partner">Profil B · partnerův porovnávací kód</label><input id="compare-partner" name="code" required autocomplete="off" spellcheck="false" placeholder="Vlož celý kód R…" maxlength="69" value="'+esc(state.partnerCode)+'"></div><fieldset class="self-scopes"><legend>Které moje části zahrnout</legend>'+checks('self',{personality:'Osobnost a temperament',roles:'Intimní role',context:'Kontext intimity',practices:'Preference aktivit'})+'</fieldset><p class="small">Tvoje odpovědi zůstanou pro běžné porovnání v prohlížeči. Intimní části vybíráš zvlášť.</p><button class="button" type="submit" '+(!mine&&!intimate?'disabled':'')+'>Porovnat se mnou →</button></form>':
    '<form data-form="compare"><div><label for="compare-a">Profil A · první porovnávací kód</label><input id="compare-a" name="a" required autocomplete="off" spellcheck="false" placeholder="Vlož celý kód R…" maxlength="69" value="'+esc(state.firstCode)+'"></div><div><label for="compare-b">Profil B · druhý porovnávací kód</label><input id="compare-b" name="b" required autocomplete="off" spellcheck="false" placeholder="Vlož celý kód R…" maxlength="69" value="'+esc(state.partnerCode)+'"></div><button class="button" type="submit">Porovnat profily →</button></form>')+
    '<p class="fine-print">Sem patří celý porovnávací kód, nikoli ID účtu. <a href="#ucet">Získat vlastní kód →</a></p></details>';
    const views=[['overview','Přehled'],['analysis','Podrobný rozbor'],['images','Obrázky']];
    return head('POROVNÁNÍ','Dva lidé.<br><em>Více porozumění.</em>','Prohlédněte si shody a rozdíly. Rozbor pomůže hledat jejich význam v konkrétních situacích.')+feedback()+entry+
    (loaded?'<nav class="wrap comparison-views" role="tablist" aria-label="Zobrazení porovnání">'+views.map(([id,title])=>'<button role="tab" id="view-tab-'+id+'" aria-controls="compare-view-'+id+'" aria-selected="'+(state.comparisonView===id)+'" tabindex="'+(state.comparisonView===id?'0':'-1')+'" data-compare-view="'+id+'">'+title+'</button>').join('')+'</nav><div id="compare-view-overview" role="tabpanel" aria-labelledby="view-tab-overview" '+(state.comparisonView==='overview'?'':'hidden')+'>'+comparisonResult()+'</div><div id="compare-view-analysis" role="tabpanel" aria-labelledby="view-tab-analysis" '+(state.comparisonView==='analysis'?'':'hidden')+'>'+aiPanel()+'</div><div id="compare-view-images" role="tabpanel" aria-labelledby="view-tab-images" '+(state.comparisonView==='images'?'':'hidden')+'>'+comparisonImages()+'</div>':
    '<div class="wrap compare-help"><strong>Jak to funguje?</strong><p>1. Načti profily. &nbsp; 2. Prohlédni si přehled. &nbsp; 3. Vyber oblasti pro podrobný rozbor.</p><p class="small">Účet k samotnému porovnání nepotřebuješ. Podobnost není předpověď vztahu. <a href="#podklady-porovnani">Podklady a limity →</a></p></div>');
  }
  function comparisonImages(){return '<section class="wrap section"><h2>Obrázky do telefonu</h2><p class="small">Vyber kartu a stáhni PNG. Sdílej jen se souhlasem obou; stažené kopie nelze zrušením kódu odvolat.</p><label class="check-row"><input type="checkbox" id="comparison-sensitive"> Přidat do náhledu sdílené intimní výsledky obou profilů</label><div id="comparison-cards" class="share-gallery"></div></section>';}

  function aiPanel(){
    const result=state.ai,all=buildAIInput(...state.comparison,Object.keys(AI_SCOPES));
    const chosen=state.aiScopes.filter(s=>all.available[s]>0),input=buildAIInput(...state.comparison,chosen);
    const options=Object.entries(AI_SCOPES).map(([id,label])=>'<label class="ai-choice '+(!all.available[id]?'unavailable':'')+'"><input type="checkbox" id="ai-scope-'+id+'" '+(chosen.includes(id)?'checked ':'')+(!all.available[id]||state.busy?'disabled ':'')+'><span><strong>'+label+'</strong><small>'+(all.available[id]?all.available[id]+' '+(all.available[id]===1?'společný podklad':all.available[id]<5?'společné podklady':'společných podkladů'):all.warnings.length?'Nepodporovaná verze nebo chybějící podklady':'Chybí v načteném porovnání')+'</small></span></label>').join('');
    const analysisHTML=(analysis,index)=>{
      const topics=analysis.topics||[],byId=new Map(topics.map(t=>[t.id,t]));
      const overview=(analysis.overview||[]).map(group=>'<section class="analysis-overview-block"><h4>'+esc(group.title)+'</h4><p>'+esc(group.text)+'</p>'+(group.ids.length?'<ul>'+group.ids.map(id=>{const t=byId.get(id);return t?'<li><strong>'+esc(t.name)+'</strong><span>'+esc(t.observation)+'</span></li>':'';}).join('')+'</ul>':'')+'</section>').join('');
      const details=topics.map(t=>'<details class="analysis-topic" data-topic="'+esc(t.id)+'"><summary><span class="analysis-label">'+esc(t.label)+'</span><strong>'+esc(t.name)+'</strong><span class="topic-observation">'+esc(t.observation)+'</span><span class="topic-expand">Význam odpovědi a otázka k rozhovoru</span></summary><div class="topic-reading"><p>'+esc(t.reading)+'</p>'+(t.question?'<p class="topic-question"><strong>K vyjasnění:</strong> '+esc(t.question)+'</p>':'')+'</div></details>').join('');
      const questions=(analysis.questions||[]).map(q=>'<article class="selected-question"><span class="analysis-label">'+esc(q.label)+'</span><strong>'+esc(q.name)+'</strong><p>'+esc(q.question)+'</p></article>').join('');
      return '<article class="ai-analysis" data-analysis-scope="'+esc(analysis.scope)+'" id="analysis-chapter-'+esc(analysis.scope)+'" role="tabpanel" aria-labelledby="analysis-tab-'+esc(analysis.scope)+'" '+(index?'hidden':'')+'><div class="analysis-heading"><span class="eyebrow">'+(index+1)+' / '+esc(AI_SCOPES[analysis.scope])+' · '+topics.length+' témat</span><h3>'+esc(analysis.title)+'</h3></div><div class="analysis-reading">'+analysis.reading.map(p=>'<p>'+esc(p)+'</p>').join('')+'</div><details class="analysis-overview-disclosure"><summary>Shody a rozdíly v číslech</summary><div class="analysis-overview">'+overview+'</div></details><h4>Význam každé odpovědi</h4><p class="small">Všechna společně zpřístupněná témata. Otevři položku pro vysvětlení a konkrétní otázku.</p><button class="text-button" type="button" data-expand-analysis="'+esc(analysis.scope)+'">Rozbalit všechny významy v této kapitole</button><div class="analysis-topics">'+details+'</div><div class="analysis-pair"><section><h4>Na co si dát pozor</h4><p>'+esc(analysis.pitfall)+'</p></section><section><h4>Co si z toho vzít</h4><p>'+esc(analysis.takeaway)+'</p></section></div>'+(questions?'<section class="analysis-questions"><h4>Čím můžete začít rozhovor</h4><p class="small">'+(analysis.aiStatus==='selected'?'AI vybrala následující otázky z připravených otázek k vašim podkladům. Jejich text ani výsledky nepřepisuje.':'Otázky vybral web podle pravidel. Úplný rozbor je dostupný i bez AI.')+'</p>'+questions+'</section>':'')+'</article>';
    };
    const output=result?.summary?.analyses?'<div class="analysis-intro"><span class="eyebrow">VÁŠ ROZBOR</span><h3>Jak tomu rozumět.<br>Co si z toho vzít.</h3><p>A je první profil v porovnání, B druhý. V režimu „Porovnat se mnou“ jsi A ty. Rozbor zahrnuje všechny společně zpřístupněné podklady: shody, nejbližší číselné hodnoty, rozdíly i otevřené odpovědi. U každého bodu si řekněte: sedí to na nás, a kdy naopak ne?</p></div>'+'<nav class="analysis-tabs" role="tablist" aria-label="Kapitoly rozboru">'+result.summary.analyses.map((a,i)=>'<button role="tab" id="analysis-tab-'+esc(a.scope)+'" aria-controls="analysis-chapter-'+esc(a.scope)+'" aria-selected="'+(i===0)+'" tabindex="'+(i===0?'0':'-1')+'" data-analysis-tab="'+esc(a.scope)+'">'+esc({personality:'Osobnost',roles:'Role',context:'Kontext',practices:'Aktivity'}[a.scope])+' <span>'+a.topics.length+'</span></button>').join('')+'</nav>'+result.summary.analyses.map(analysisHTML).join(''):result?'<p class="feedback">'+esc(result.message||'Rozbor není dostupný.')+'</p>':state.busy?'<p class="analysis-loading" role="status">Připravuji úplný rozbor a výběr otázek ke shodám i odlišným odpovědím.</p>':'<p class="small analysis-empty">Tady se objeví úplný rozbor vybraných kategorií a otázky ke společným bodům i odlišným odpovědím.</p>';
    const fixed=input.facts.filter(f=>['boundary','unknown'].includes(f.kind)).map(f=>'<div class="ai-fixed"><strong>'+esc(f.name)+'</strong><p>'+esc(factValues(f))+'</p><p>'+esc(factNote(f))+'</p><small>Pevné pravidlo · tento bod AI nepřepisuje</small></div>').join('');
    const preview=input.facts.map(f=>'<li><strong>'+esc(f.name)+'</strong><span>'+esc(factValues(f))+'</span><small>'+esc(factNote(f))+'</small></li>').join('');
    return '<section class="wrap section ai-lab" id="ai-explanation"><span class="eyebrow">VOLITELNÉ · MÍSTNÍ MODEL · EXPERIMENT</span><h2>2. Čemu chcete porozumět?</h2><p>Vyber oblasti, kterým chcete lépe porozumět. Intimní části přidáváš dobrovolně.</p><fieldset class="ai-choices"><legend>Co zahrnout do rozboru?</legend>'+options+'</fieldset><details class="journey-help"><summary>Proč nejde některou oblast vybrat?</summary><p>Musí být vyplněná a zpřístupněná u obou profilů. Při porovnání s vlastními odpověďmi ji zahrň ve vstupním formuláři a porovnání načti znovu.</p></details><details class="ai-preview"><summary>Zkontrolovat vybrané podklady ('+input.facts.length+')</summary>'+(preview?'<ul>'+preview+'</ul>':'<p>Vyber alespoň jednu dostupnou kategorii.</p>')+'</details><p class="small">Tlačítkem odešleš vybrané podklady obou profilů místnímu modelu na serveru tohoto webu. Použij jen data, k jejichž zpracování máte oba svolení. Kódy ani nevybrané kategorie se modelu neposílají.</p><button class="button" data-p="ai-summary" '+(state.busy||!input.facts.length?'disabled':'')+'>'+(state.busy?'Píšu váš rozbor…':'Vytvořit rozbor')+'</button><p class="small ai-caveat">Výsledky a jejich vysvětlení sestavují pevná pravidla. AI jen vybírá otázky k rozhovoru. Nejde o validovaný psychologický posudek. <a href="#podklady-porovnani">Podklady a limity →</a></p>'+(result?.summary?'':fixed)+'<div class="ai-output ai-report" id="ai-result" tabindex="-1" aria-live="polite">'+output+(result?.status==='partial'?'<p class="feedback">'+esc(result.message)+'</p>':'')+'</div>'+(result?.model?'<details class="analysis-technical"><summary>Technické údaje rozboru</summary><p class="fine-print">'+esc(result.model)+' · '+esc(result.seconds)+' s · '+esc(result.promptVersion)+'</p></details>':'')+'</section>';
  }
  function numberRows(rows,long=false){return rows.map(r=>`<article class="compare-row ${long?'long-row':''}"><h3>${esc(r.name)}</h3><div class="pair-values"><span><small>Profil A</small><b>${fmt(r.a)}</b></span><span><small>Profil B</small><b>${fmt(r.b)}</b></span><span><small>Rozdíl</small><b>${r.complete?fmt(r.delta):'—'}</b></span></div>${r.complete?`<div class="pair-track" role="img" aria-label="A ${fmt(r.a)}, B ${fmt(r.b)}, rozsah 1 až 5"><i class="point-a" style="left:${(r.a-1)/4*100}%">A</i><i class="point-b" style="left:${(r.b-1)/4*100}%">B</i></div><div class="axis-labels"><span>1</span><span>5</span></div>`:'<p class="small">U jednoho nebo obou profilů chybí číselné odpovědi. Rozdíl nepočítáme.</p>'}</article>`).join('');}
  function comparisonResult(){
    const [a,b]=state.comparison,comp=compareProfiles(a,b),sorted=comp.personality.filter(x=>x.complete).sort((x,y)=>x.delta-y.delta),groups=['shared','talk','boundary','unknown'];
    const chapter=(id,title,n,body,open=false)=>'<details class="wrap comparison-category" '+(open?'open':'')+'><summary><strong>'+title+'</strong><span>'+n+' témat <b aria-hidden="true">＋</b></span></summary><div class="comparison-category-body">'+body+'</div></details>';
    return '<section class="wrap comparison-at-glance"><div class="compare-identities"><span><b>A</b> '+(state.comparisonIsSelf?'Moje odpovědi':'První profil')+'</span><span><b>B</b> '+(state.comparisonIsSelf?'Partnerův profil':'Druhý profil')+'</span></div><p class="small">Popis vlastních odpovědí, bez procent kompatibility. Dotazníky nejsou validované. <a href="#podklady-porovnani">Zdroje a limity →</a></p>'+(comp.same?'<p class="feedback">Oba kódy odkazují na stejný výsledek.</p>':'')+comp.warnings.map(w=>'<p class="feedback">'+esc(w)+'</p>').join('')+
    '<div class="comparison-highlights">'+(sorted.length?'<div><span>NEJBLIŽŠÍ HODNOTY POVAHY</span><strong>'+sorted.filter(x=>x.delta===sorted[0].delta).map(x=>esc(x.name)).join(', ')+'</strong><small>Číselný rozdíl '+fmt(sorted[0].delta)+' na stupnici 1–5; nejde o ověřenou shodu.</small></div>':'')+(comp.practices.length?'<div><span>PREFERENCE AKTIVIT</span><strong>'+comp.practices.filter(x=>x.kind==='shared').length+' společných zájmů</strong><small>'+comp.practices.filter(x=>x.kind==='talk').length+' k vyjasnění · '+comp.practices.filter(x=>x.kind==='boundary').length+' s hranicí „Nechci“. Zájem není souhlas.</small></div>':'')+'</div><div class="actions"><button class="button" data-compare-view="analysis">Jak tomu rozumět? Otevřít rozbor →</button></div><details class="comparison-meta-details"><summary>Údaje o načtených výsledcích</summary><p>A: '+date(a.created)+' · '+esc(a.id)+'<br>B: '+date(b.created)+' · '+esc(b.id)+'</p><p>Společně zpřístupněno: '+comp.common.map(x=>names[x]).join(', ')+'.</p></details></section>'+
    (comp.personality.length?chapter('personality','Osobnost a temperament',comp.personality.length,'<p class="small">Průměry odpovědí 1–5. Rozdíl neříká, kdo má pravdu nebo zda se k sobě hodíte.</p><div class="comparison-grid">'+numberRows(comp.personality)+'</div><div class="temperament-pair"><h3>Historická mapa temperamentu</h3><p>A: <strong>'+mapTemperament(a.personality)+'</strong> · B: <strong>'+mapTemperament(b.personality)+'</strong></p><p class="small">Ilustrativní převod stejných odpovědí, ne další test. <a href="#podklady-temperament">Pravidla mapy →</a></p></div>',true):'')+
    (comp.roles.length?chapter('roles','Intimní role',comp.roles.length,'<p class="small">Zájem o vlastní roli podle dvou nevalidovaných výroků, 1–5. Role neurčují identitu ani souhlas.</p><div class="comparison-grid">'+numberRows(comp.roles)+'</div>'):'')+
    (comp.context.length?chapter('context','Podmínky pro intimitu',comp.context.length,'<p class="small">Přímé odpovědi na jednotlivé výroky. Bez společného skóre.</p><div class="comparison-grid">'+numberRows(comp.context,true)+'</div>'):'')+
    (comp.practices.length?chapter('practices','Preference aktivit',comp.practices.length,'<p class="consent-note">Společný zájem není souhlas. „Možná“ nepotvrzuje zájem. „Nechci“ respektujte.</p><div class="practice-comparison">'+groups.map(kind=>'<section class="practice-group"><h3>'+comparisonLabels[kind]+'</h3>'+ (comp.practices.filter(p=>p.kind===kind).map(p=>'<article><strong>'+esc(p.name)+'</strong><span>A: '+esc(p.a)+'</span><span>B: '+esc(p.b)+'</span></article>').join('')||'<p class="small">Žádné položky.</p>')+'</section>').join('')+'</div>'):'')+
    '<div class="wrap final-actions"><button class="text-button" data-p="clear-comparison">Vymazat porovnání z tohoto panelu</button></div>';
  }

  function paintComparisonCards(){const target=document.getElementById('comparison-cards');if(!target||!state.comparison)return;cards.clear();const comp=compareProfiles(...state.comparison),sensitive=document.getElementById('comparison-sensitive').checked;const specs=[];const contextNames={desire:'Spontánní touha',responsive:'Touha v reakci na blízkost',variable:'Proměnlivost chuti',close:'Emoční blízkost',privacy:'Soukromí a bezpečí',stress:'Stres a rušení',familiar:'Známé prostředí',novel:'Novost a objevování',communication:'Otevřená komunikace',boundaries:'Sdělování hranic',talkfirst:'Domluva předem',aftercare:'Péče po kontaktu'};
    const add=(id,title,rows,note)=>specs.push({id,title,tag:'Dva profily · A / B',subtitle:'Porovnání vlastních odpovědí · bez norem a předpovědi vztahu',rows,note,source:'osobnosti. · #podklady-porovnani · vlastní nevalidované otázky'});
    if(comp.personality.length)add('povaha','Dva pohledy na povahu',comp.personality.map(r=>({label:r.name,detail:`A ${fmt(r.a)}  ·  B ${fmt(r.b)}  ·  rozdíl ${fmt(r.delta)}`})),'Stupnice 1–5. Rozdíly nejsou skóre kompatibility.');
    if(sensitive&&comp.roles.length)add('role','Role vedle sebe',comp.roles.map(r=>({label:r.name,detail:`A ${fmt(r.a)}  ·  B ${fmt(r.b)}  / 5`})),'Deklarované konsenzuální zájmy dospělých, ne souhlas.');
    if(sensitive&&comp.practices.length)add('preference','Zájmy a hranice',comp.practices.map(r=>({label:r.name,detail:comparisonLabels[r.kind]})),'Společný zájem není souhlas. „Nechci“ respektujte.');
    if(sensitive&&comp.context.length){for(let i=0;i<2;i++)add(`kontext-${i+1}`,`Kontext intimity ${i+1}/2`,comp.context.slice(i*6,i*6+6).map((r,j)=>({label:contextNames[r.id],detail:`A ${fmt(r.a)}  ·  B ${fmt(r.b)}  / 5`})), 'Jednotlivé odpovědi 1–5, nikoli předpověď chování.');}
    target.innerHTML=specs.length?specs.map(s=>`<article class="share-preview"><img id="comparison-card-${s.id}" alt="Náhled porovnání: ${s.title}"><button class="button secondary" data-p="download-card" data-id="${s.id}">Stáhnout ${s.title} .png</button></article>`).join(''):'<p class="small">Zatím žádná sdílená osobnostní škála. Intimní karty můžeš přidat volbou výše.</p>';
    specs.forEach(s=>{const c=drawCard(s);cards.set(s.id,c);document.getElementById(`comparison-card-${s.id}`).src=c.toDataURL('image/png');});
  }
  function route(hash,load=true){if(hash==='#podklady-porovnani'){show(methodNav('comparison')+comparisonSources(),'Podklady porovnání','science');return true;}if(hash!=='#ucet'&&hash!=='#porovnani')return false;show(hash==='#ucet'?accountPage():comparePage(),hash==='#ucet'?'Účet a výsledky':'Porovnání profilů',hash==='#ucet'?'account':'compare');if(hash==='#porovnani')paintComparisonCards();if(load&&secure()&&hash==='#ucet')run(async()=>{state.ready=false;await api();await refreshList();await savePending();});return true;}
  document.addEventListener('submit',event=>{const form=event.target.closest('[data-form]');if(!form)return;event.preventDefault();const type=form.dataset.form,fields=new FormData(form);
    if(['login','register','legacy-login','upgrade-account','change-password'].includes(type)){
      const payload=Object.fromEntries(fields);payload.remember=fields.get('remember')==='on';state.authNickname=String(fields.get('nickname')||state.authNickname);state.authRemember=payload.remember;
      if(['register','upgrade-account','change-password'].includes(type)&&payload.password!==payload.repeat){state.error='Hesla se neshodují. Zadej je prosím znovu.';refresh();return;}
      delete payload.repeat;
      const previous=state.account||state.lastAccount;
      run(async()=>{const data=await api(type,payload);if(previous&&previous!==data.account&&!state.pendingSave)clear();state.lastAccount=data.account;state.selection=null;state.preview=null;state.shareCode=null;state.comparison=null;state.notice=type==='change-password'?'Heslo změněno. Ostatní přihlášení byla odhlášena.':'Přihlášeno. Uložené výsledky najdeš níže.';await refreshList();await savePending();});
    }
    if(type==='save'){const p=document.getElementById('save-personality').checked,i=document.getElementById('save-intimacy').checked;const snapshot={version:'profile-1',ipipVersion:VERSION,intimacyVersion:INTIMACY_VERSION,personality:p?{...getPersonality()}:{},intimacy:i?{...getIntimacy()}:{}};run(async()=>{const r=await api('save',{snapshot});await refreshList();state.notice=`Uloženo jako ${r.id}. Změny v dotazníku se do tohoto snímku automaticky nepřenášejí.`;});}
    if(type==='share'){state.shareCode=null;const scopes=Object.keys(names).filter(id=>document.getElementById(`grant-${id}`).checked);state.grantScopes=scopes;if(!scopes.length){state.error='Vyber alespoň jednu kategorii.';refresh();return;}run(async()=>{const r=await api('load',{id:state.selection});const {score}=await import('./instrument.mjs');const {roleScores,CONTEXT_ITEMS,PRACTICES}=await import('./extensions-data.mjs');const preview={};if(scopes.includes('personality'))preview.personality=Object.fromEntries(score(r.snapshot.personality).map(x=>[x.name,x.mean]));if(scopes.includes('roles'))preview.roles=Object.fromEntries(roleScores(r.snapshot.intimacy).map(x=>[x.name,x.mean]));for(const [name,items] of [['context',CONTEXT_ITEMS],['practices',PRACTICES]])if(scopes.includes(name))preview[name]=Object.fromEntries(items.filter(x=>r.snapshot.intimacy[x.id]!==undefined&&r.snapshot.intimacy[x.id]!=='skip').map(x=>[x.text||x.name,r.snapshot.intimacy[x.id]]));state.preview={scopes,html:previewHTML(preview)};});}
    if(type==='compare-self'){
      const code=String(fields.get('code')).trim(),scopes=Object.keys(names).filter(id=>document.getElementById('self-'+id).checked);
      if(!scopes.length){state.error='Vyber alespoň jednu svou kategorii.';refresh();return;}
      if(!answerCount(getPersonality())&&!intimateCount(getIntimacy())){state.error='Nejprve vyplň svůj profil.';refresh();return;}
      state.partnerCode=code;state.comparisonView='overview';const own=currentPublicProfile(getPersonality(),getIntimacy(),scopes);state.comparison=null;state.ai=null;state.aiScopes=['personality'];
      run(async()=>{const r=await api('read-shared',{code});state.comparison=[own,r.profile];state.comparisonIsSelf=true;state.notice='A = moje odpovědi v okamžiku porovnání. B = partnerův uložený výsledek. Další změny testu se projeví až po novém porovnání.';});
    }
    if(type==='compare'){state.comparisonIsSelf=false;state.ai=null;state.aiScopes=['personality'];const a=String(fields.get('a')).trim(),b=String(fields.get('b')).trim();state.firstCode=a;state.partnerCode=b;state.comparisonView='overview';state.comparison=null;run(async()=>{const r=await api('compare',{a,b});state.comparison=r.profiles;state.notice='Porovnání načteno. Kódy se neukládají do adresy ani do historie prohlížeče.';});}
  });
  document.addEventListener('click',event=>{const b=event.target.closest('[data-p]');if(!b||state.busy)return;const action=b.dataset.p,id=b.dataset.id;
    if(action==='compare-mode'){state.compareMode=b.dataset.mode;state.comparisonView='overview';state.notice='';state.comparison=null;state.ai=null;state.aiScopes=['personality'];refresh();}
    if(action==='ai-summary'&&state.comparison){
      const pair=state.comparison,available=buildAIInput(...pair,Object.keys(AI_SCOPES)).available;
      const scopes=state.aiScopes.filter(s=>available[s]>0);if(!scopes.length)return;
      state.ai=null;run(async()=>{
        state.notice='Připravuji rozbor vybraných kategorií a výběr otázek k rozhovoru.';refresh();
        document.getElementById('ai-result')?.scrollIntoView({block:'start'});
        let result;try{result=await api('ai-explain',{scopes,a:selectForAI(pair[0],scopes),b:selectForAI(pair[1],scopes)});}catch(error){result={status:'error',message:error.message};}
        if(state.comparison!==pair)return;
        state.ai=result;state.aiFocus=true;state.notice='Rozbor vybraných podkladů je hotový. Vysvětlení sestavují pevná pravidla; AI pouze vybírá z připravených otázek.';
      });
    }

    if(action==='auth-mode'){state.authMode=b.dataset.mode;state.error='';refresh();}
    if(action==='cancel-save'){state.pendingSave=null;state.notice='Uložení na účet zrušeno. Odpovědi zůstaly v této relaci.';refresh();}
    if(action==='retry-save')run(savePending);
    if(action==='copy-code'){navigator.clipboard.writeText(state.shareCode.code).then(()=>{b.textContent='Zkopírováno';}).catch(()=>{b.textContent='Označ a zkopíruj kód z pole výše';});}
    if(action==='logout')confirmAction('Odhlásit a vyčistit panel?','Uložené výsledky zůstanou v účtu. Odpovědi, jejich místní kopie v prohlížeči a načtené porovnání se odstraní.',async()=>{await api('logout');state.account=null;state.lastAccount=null;state.pendingSave=null;state.selection=null;state.preview=null;state.shareCode=null;state.comparison=null;clear();await refreshList();state.notice='Odhlášeno. Tento panel byl vyčištěn.';});
    if(action==='select-share'){state.selection=id;state.grantScopes=['personality'];state.preview=null;state.shareCode=null;refresh();document.getElementById('share-builder').scrollIntoView({block:'start'});}
    if(action==='create-share')run(async()=>{const r=await api('share',{id:state.selection,scopes:state.preview.scopes});state.shareCode=r;state.preview=null;await refreshList();});
    if(action==='load')confirmAction('Načíst uložený výsledek?','Nahradí odpovědi těch testů, které tento snímek obsahuje. Druhý test zůstane zachovaný. Novější neuložené změny nahrazovaného testu ztratíš; při zapnutém zapamatování se aktualizuje i místní kopie.',async()=>{const r=await api('load',{id});restore(r.snapshot);state.notice='Odpovědi načtené do stránky. Můžeš je upravit a uložit jako nový výsledek.';});
    if(action==='delete-profile')confirmAction('Smazat uložený výsledek?','Odstraní tento snímek ze serveru a zruší všechny jeho porovnávací kódy. Aktuální odpovědi v panelu a stažené kopie zůstanou.',async()=>{await api('delete-profile',{id});if(state.selection===id){state.selection=null;state.preview=null;state.shareCode=null;}state.comparison=null;await refreshList();state.notice='Uložený výsledek i jeho kódy byly odstraněny.';});
    if(action==='revoke')run(async()=>{await api('revoke',{id});state.shareCode=null;state.comparison=null;await refreshList();state.notice='Kód byl zrušen. Dříve načtené kopie u druhých lidí tím nezmizí.';});
    if(action==='delete-account')confirmAction('Smazat celý účet?','Trvale odstraní účet, všechny jeho výsledky a kódy. Vyčistí i místní kopii v prohlížeči, odpovědi a porovnání v tomto panelu. Stažené kopie zůstanou.',async()=>{const secret=document.getElementById('delete-secret').value;document.getElementById('delete-secret').value='';await api('delete-account',{confirm:'SMAZAT',secret});state.account=null;state.lastAccount=null;state.pendingSave=null;state.selection=null;state.preview=null;state.shareCode=null;state.comparison=null;clear();await refreshList();state.notice='Účet a jeho uložená data byly smazány.';},true);
    if(action==='clear-comparison'){state.comparison=null;state.ai=null;state.partnerCode='';state.firstCode='';state.comparisonView='overview';state.aiScopes=['personality'];cards.clear();state.notice='Porovnání bylo odstraněno z tohoto panelu.';refresh();}
    if(action==='download-card'){const c=cards.get(id);if(c)saveCanvas(c,`osobnosti-porovnani-${id}.png`);}
  });
  document.addEventListener('change',e=>{if(e.target.id.startsWith('ai-scope-')){
      const focusId=e.target.id;
      state.aiScopes=Object.keys(AI_SCOPES).filter(id=>document.getElementById('ai-scope-'+id)?.checked);
      state.ai=null;state.notice='';document.getElementById('profile-feedback').innerHTML='';
      document.getElementById('ai-explanation').outerHTML=aiPanel();
      document.getElementById(focusId)?.focus({preventScroll:true});
      return;
    }if(e.target.id.startsWith('self-'))state.selfScopes=Object.keys(names).filter(id=>document.getElementById('self-'+id)?.checked);if(e.target.id==='comparison-sensitive')paintComparisonCards();if(e.target.id.startsWith('grant-')){state.grantScopes=Object.keys(names).filter(id=>document.getElementById(`grant-${id}`).checked);state.preview=null;document.getElementById('grant-preview').innerHTML=grantDetails();}});
  function grantDetails(){
    if(state.preview)return `<div class="grant-detail"><h3>Náhled toho, co zpřístupníš</h3>${state.preview.html}<p>Kód uvidí tyto části každý, komu ho předáš. Platnost 7 dní; lze kdykoli zrušit.</p><button class="button" data-p="create-share">Zpřístupnit tento výběr a vytvořit kód</button></div>`;
    if(state.shareCode)return `<div class="grant-detail"><h3>Kód je připravený.</h3><p>Platí do ${date(state.shareCode.expires)}. Zkopíruj celý řádek; po zavření stránky ho už nezobrazíme.</p><label for="created-code">Porovnávací kód</label><textarea id="created-code" rows="3" readonly>${esc(state.shareCode.code)}</textarea><div class="actions"><button class="button secondary" data-p="copy-code">Zkopírovat kód</button><a class="text-link" href="#porovnani">Přejít na porovnání →</a></div></div>`;
    return '';
  }
  document.addEventListener('input',e=>{if(e.target.id==='auth-nickname')state.authNickname=e.target.value;});
  document.addEventListener('focusout',async e=>{const field=e.target;if(field.id!=='auth-nickname'||!field.validity.valid||!['register','upgrade-account'].includes(field.form?.dataset.form))return;const value=field.value,output=document.getElementById('nickname-status');if(!output)return;output.textContent='Ověřuji dostupnost…';try{const result=await api('check-nickname',{nickname:value});if(field.isConnected&&field.value===value)output.textContent=result.available?'Nickname je volný.':'Tento nickname už někdo používá.';}catch{if(output.isConnected)output.textContent='Dostupnost ověříme při vytvoření účtu.';}});
  return {route,cancelSave:()=>{state.pendingSave=null;},saveCompleted:(scope)=>{state.pendingSave={scope,snapshot:{version:'profile-1',ipipVersion:VERSION,intimacyVersion:INTIMACY_VERSION,personality:scope==='personality'?{...getPersonality()}:{},intimacy:scope==='intimacy'?{...getIntimacy()}:{}}};go('#ucet');},clearComparison:()=>{state.comparison=null;state.ai=null;state.partnerCode='';state.firstCode='';state.comparisonView='overview';state.aiScopes=['personality'];cards.clear();}};
}
